#include <math.h>
#include <string.h>

#include "fv_image_check.h"
#include "fv_result.h"
#include "fv_selftest.h"
#include "fv_vision.h"
#include "model2_infer.h"
#include "preprocess_rgb565.h"

/* generated by tools/firmware/gen_selftest_data.py */
extern const int8_t g_st_inputs[FV_ST_N_INPUTS][FV_IN_BYTES_ST];
extern const int8_t g_st_expected_raw[FV_ST_N_INPUTS][FV_ST_RAW];
extern const int32_t g_st_expected_result[FV_ST_N_INPUTS][5];   /* fruit, quality_state, grade, consistency, image_flags */
extern const float g_st_m2_input[8];
extern const float g_st_m2_expected_probs[3];
extern const int32_t g_st_m2_expected_class;
#ifdef FV_ST_WITH_FRAME
extern const uint8_t g_st_frame[FV_ST_FRAME_W * FV_ST_FRAME_H * 2];   /* RGB565 big-endian, row-major */
extern const uint32_t g_st_frame_expected_hash;
extern const int8_t g_st_frame_expected_raw[FV_ST_RAW];
extern const int32_t g_st_frame_expected_result[5];

static uint32_t fnv1a(const int8_t *p, size_t n) {
    uint32_t h = 2166136261u;
    for (size_t i = 0; i < n; ++i) { h ^= (uint8_t)p[i]; h *= 16777619u; }
    return h;
}
#endif

static uint32_t no_cycles(void) { return 0u; }

void fv_selftest_run(fv_selftest_t *st, const uint8_t *model, uint8_t *pers, uint32_t pers_bytes, uint8_t *np,
                     uint32_t np_bytes, uint32_t (*cycles)(void)) {
    if (!cycles) cycles = no_cycles;
    st->magic = FV_ST_MAGIC_RUNNING;
    st->version = FV_ST_VERSION;
    st->n_inputs = FV_ST_N_INPUTS;
    st->pass = 0;
    int ok = 1;
    st->init_status = fv_vision_init(model, pers, pers_bytes, np, np_bytes);
    st->arena_used_bytes = (uint32_t)fv_vision_arena_used_bytes();
    if (st->init_status != FV_OK) ok = 0;
    for (int i = 0; i < FV_ST_N_INPUTS; ++i) {
        st->invoke_status[i] = FV_ERR_MODEL;
        if (st->init_status != FV_OK) continue;
        size_t n = 0;
        int8_t *in = fv_vision_input(&n);
        if (!in || n != FV_IN_BYTES_ST) { ok = 0; continue; }
        memcpy(in, g_st_inputs[i], n);
        st->image_flags[i] = fv_image_check(in, NULL);
        fv_vision_raw_t raw;
        const uint32_t c0 = cycles();
        st->invoke_status[i] = fv_vision_invoke(&raw);
        st->invoke_cycles[i] = cycles() - c0;
        if (st->invoke_status[i] != FV_OK) { ok = 0; continue; }
        uint32_t mm = 0;
        for (int k = 0; k < FV_ST_RAW; ++k) {
            const int8_t v = raw.q[k / FV_MAX_CLASSES][k % FV_MAX_CLASSES];
            st->raw[i][k] = v;
            int d = (int)v - (int)g_st_expected_raw[i][k];
            if (d < 0) d = -d;
            if (d) mm++;
            if (d > st->max_abs_diff) st->max_abs_diff = d;
        }
        st->raw_mismatches[i] = mm;
        if (mm) ok = 0;
        fv_image_result_t r;
        fv_result_from_raw(&raw, &r);
        st->fruit[i] = r.fruit;
        st->quality_state[i] = r.quality_state;
        st->grade[i] = r.grade;
        st->consistency[i] = r.consistency;
        const int32_t *e = g_st_expected_result[i];
        if (r.fruit != e[0] || (int32_t)r.quality_state != e[1] || r.grade != e[2] || (int32_t)r.consistency != e[3] ||
            (int32_t)st->image_flags[i] != e[4]) {
            st->result_mismatches++;
            ok = 0;
        }
    }
#ifdef FV_ST_WITH_FRAME
    /* offline camera-format frame: firmware preprocessing (160x120 RGB565 BE -> 80x80 int8) -> model -> validation */
    st->frame_present = 1;
    st->frame_invoke_status = FV_ERR_MODEL;
    if (st->init_status == FV_OK) {
        size_t n = 0;
        int8_t *in = fv_vision_input(&n);
        uint32_t c0 = cycles();
        st->frame_pp_status = in ? fv_rgb565_to_input_int8(g_st_frame, FV_ST_FRAME_W, FV_ST_FRAME_H, 1, in) : -1;
        st->frame_pp_cycles = cycles() - c0;
        if (st->frame_pp_status == 0 && n == FV_IN_BYTES_ST) {
            st->frame_input_hash = fnv1a(in, n);
            st->frame_input_hash_ok = st->frame_input_hash == g_st_frame_expected_hash;
            st->frame_image_flags = fv_image_check(in, NULL) | fv_frame_dims_check(FV_ST_FRAME_W, FV_ST_FRAME_H);
            fv_vision_raw_t raw;
            c0 = cycles();
            st->frame_invoke_status = fv_vision_invoke(&raw);
            st->frame_invoke_cycles = cycles() - c0;
            if (st->frame_invoke_status == FV_OK) {
                for (int k = 0; k < FV_ST_RAW; ++k) {
                    st->frame_raw[k] = raw.q[k / FV_MAX_CLASSES][k % FV_MAX_CLASSES];
                    if (st->frame_raw[k] != g_st_frame_expected_raw[k]) st->frame_raw_mismatches++;
                }
                fv_image_result_t r;
                fv_result_from_raw(&raw, &r);
                st->frame_fruit = r.fruit;
                const int32_t *e = g_st_frame_expected_result;
                st->frame_result_ok = r.fruit == e[0] && (int32_t)r.quality_state == e[1] && r.grade == e[2] &&
                                      (int32_t)r.consistency == e[3] && (int32_t)st->frame_image_flags == e[4];
            }
        }
    }
    if (!(st->frame_pp_status == 0 && st->frame_input_hash_ok && st->frame_invoke_status == FV_OK &&
          st->frame_raw_mismatches == 0 && st->frame_result_ok))
        ok = 0;
#endif
    const m2_raw_t m = {g_st_m2_input[0], g_st_m2_input[1], g_st_m2_input[2], g_st_m2_input[3],
                        g_st_m2_input[4], g_st_m2_input[5], g_st_m2_input[6], g_st_m2_input[7]};
    int cls = -1;
    st->m2_status = m2_predict(&m, st->m2_probs, &cls);
    st->m2_class = cls;
    st->m2_ok = st->m2_status == M2_OK && cls == g_st_m2_expected_class;
    for (int k = 0; k < 3; ++k)
        if (!(fabsf(st->m2_probs[k] - g_st_m2_expected_probs[k]) < 1e-4f)) st->m2_ok = 0;
    if (!st->m2_ok) ok = 0;
    st->pass = (uint32_t)ok;
}
